 auto start=std::chrono::steady_clock::now();batch(h,d,s);times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/R);auto rp=get(s.dev[0],s.host[0].size()),co=get(s.dev[1],s.host[1].size()),v=get(s.dev[2],s.host[2].size()),perm=get(s.dev[3],s.host[3].size()),out=get(s.dev[4],s.host[4].size());ok&=rp==s.host[0]&&v==s.host[2];std::vector<uint32_t>record(rp.begin(),rp.end()-G);record.insert(record.end(),co.begin(),co.end()-G);record.insert(record.end(),perm.begin(),perm.end()-G);record.insert(record.end(),out.begin(),out.end()-G);for(size_t i=0;i<record.size();i++){mismatches+=record[i]!=oracle[c.oo+i];ok&=record[i]==oracle[c.oo+i];}values.insert(values.end(),record.begin(),record.end());for(auto&a:{rp,co,v,perm,out})for(size_t j=a.size()-G;j<a.size();j++){guards.push_back(a[j]);ok&=a[j]==S;}}
 auto art=prefix;art.insert(art.end(),values.begin(),values.end());art.insert(art.end(),guards.begin(),guards.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(trial)+".bin";std::ofstream(path,std::ios::binary).write((char*)art.data(),art.size()*4);double total=0;for(auto t:times)total+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":null,\"error_metric_scope\":\"Exactrowptr/column/permutation/valuebitmismatchflag\",\"mismatch_output_words\":%d,\"timing_region\":\"sum3cases_meanR1000_stateful_cusparseXcsrsort_plusGather_device_complete\",\"jit_excluded\":true,\"internal_repeats\":1000,\"component_time_seconds\":[",trial,total,ok?"true":"false",values.size()+guards.size(),mismatches>0?1:0,mismatches);for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),art.size());fflush(stdout);if(!ok)return 1;}
